    gl_tartil: 'ترتیل',
    gl_tartil_t: 'ٹھہر ٹھہر کر، صاف اور سوچ سمجھ کر ایک ایک لفظ پڑھنا۔ اس کی بنیاد 73:4 ہے۔',
