    sichern_solange_die_app_in_der_testphase: '<b>محفوظ کریں:</b> اتقان اکاؤنٹ کے بغیر بھی چلتا ہے۔ تب آپ کی پیش رفت اسی آلے پر رہتی ہے اور آپ اسے پروفائل › محفوظ نقل میں «پروفائل محفوظ کریں» سے محفوظ کر سکتے ہیں۔ اختیاری اکاؤنٹ (ای میل کوڈ سے لاگ اِن) کے ساتھ وہ فرینکفرٹ کے ایک سرور پر بھی رہتی ہے اور آپ کے تمام آلات پر موجود ہوتی ہے۔',
