  evidenz: {
    eintrag: 'شواہد اور حدود',
    titel: 'شواہد اور حدود',
    untertitel: 'سیکھنے کا ماڈل کیا ثابت کرتا ہے اور کیا نہیں',
    kern: '<b>شواہد کی بنیاد پر بنایا گیا، ثابت شدہ نہیں۔</b> اتقان اچھی طرح پرکھے ہوئے سیکھنے کے اصولوں پر قائم ہے۔ یہ منصوبہ قرآن کو یاد رکھنے میں آپ کی مدد کرتا ہے یا نہیں، اسے ہم نے ابھی انسانوں پر اپنی کسی تحقیق میں نہیں جانچا۔',
    tut_h: 'سیکھنے کا ماڈل کیا کرتا ہے',
    tut_1: '<b>وقفے آپ کی مہارت کے ساتھ بڑھتے ہیں۔</b> جو پکا ہے وہ کم بار لوٹتا ہے، جو ڈگمگاتا ہے وہ زیادہ بار۔',
    tut_2: '<b>غلطی کا مطلب اگلے دن جانچ ہے۔</b> یہ اس وقت ہوتا ہے جب کسی حصے کی تقریباً چوتھائی یا اس سے زیادہ آیات غلط ہوں۔',
    tut_3: '<b>دور برقرار رہتا ہے۔</b> دن کی تقریباً ایک چوتھائی جگہیں اس حصے کو ملتی ہیں جو سب سے زیادہ مدت سے انتظار میں ہے، تاکہ کچھ نظرانداز نہ ہو۔',
    tut_4: '<b>پہلی جانچ پہلے آتی ہے۔</b> جو حصے آپ نے پہلے یاد کیے اور جنہیں اتقان نے کبھی نہیں جانچا، انہیں بہت سی جگہیں ملتی ہیں جب تک ہر ایک کی باری ایک بار نہ آ جائے۔',
    tut_5: '<b>حفظ کی رفتار دہرائی کی حفاظت کرتی ہے۔</b> نیا سبق تبھی شروع ہوتا ہے جب آج دہرائی کی انتظار کرتی مقدار آپ کے روزانہ ورد سے زیادہ نہ ہو اور تین سے زیادہ سبق جاری نہ ہوں۔',
    stuetzt_h: 'یہ کس پر قائم ہے',
    stuetzt_1: 'وقفوں سے دہرانے اور بھولنے کے منحنی پر تحقیق پر۔ وہ دکھاتی ہے کہ جو یادداشت سے سنا کر پھر متن سے ملاتا ہے وہ زیادہ یاد رکھتا ہے، اور موزوں وقفوں سے دہرائی ٹھونسی ہوئی دہرائی سے زیادہ ٹکتی ہے۔ یہ مطالعے زیادہ تر ان اسکولی اور جامعاتی طلبہ پر ہوئے جو الفاظ، حقائق اور نثر سیکھ رہے تھے، قرآن نہیں۔',
    stuetzt_2: 'ہم نے منصوبے کو سمولیشن میں بھی آزمایا: {welten} الگ الگ بنائی گئی آزمائشی دنیاؤں میں، جہاں یادداشت مختلف طریقوں سے بھولتی ہے۔ منصوبہ ان کے اصول نہیں جانتا۔ موازنہ پہلے کے طریقوں «کلاسیکی» اور «طویل مدتی» سے کیا گیا۔',
    stuetzt_3: 'نتیجہ: روزانہ مقدار (2، 3، 5 یا 8 حصے) کے مطابق منصوبے نے سمولیشن کے دوسرے سال میں «کلاسیکی» سے {kvon} سے {kbis} فیصدی پوائنٹ زیادہ اور «طویل مدتی» سے {lvon} سے {lbis} فیصدی پوائنٹ زیادہ یاد رکھا۔ یہ معتدل برتری ہے، جو وقت کم ہونے پر سب سے بڑی ہے۔ روزانہ آٹھ حصوں پر منصوبہ «طویل مدتی» کے تقریباً برابر ہے۔',
    stuetzt_4: 'منصوبے کی کمزوریاں بھی ہیں: بعض اقسام کی دنیاؤں میں وہ بہترین پچھلے طریقے سے {schwach} فیصدی پوائنٹ تک پیچھے رہا، مثلاً جب بھولنے کی شکل مختلف ہو یا جب لمبے وقفے یادداشت کو کچھ فائدہ نہ دیں۔ سب سے کمزور دس فیصد حصے «طویل مدتی» میں کچھ بہتر رہے، کیونکہ منصوبہ پرانے حصوں کے لیے جگہیں رکھتا ہے۔',
    stuetzt_5: 'تمام اعداد سمولیشن سے آئے ہیں۔ ناپا یہ گیا کہ کسی حصے کو بغیر غلطی کے سنانے کا امکان کتنا ہے۔ اعداد بنائی گئی دنیاؤں کو بیان کرتے ہیں، آپ کو نہیں۔',
    nicht_h: 'کیا ثابت نہیں',
    nicht_1: 'حقیقی انسانوں پر کوئی ثبوت نہیں۔ ہمارے علم میں کوئی مطالعہ نہیں جو قرآن حفظ کرنے کے لیے دہرائی کے منصوبوں کا موازنہ کرے۔',
    nicht_2: 'سمولیشن کے نتائج ماڈل کی گئی دنیاؤں پر لاگو ہوتے ہیں۔ حقیقت ان کے اندر ہے یا نہیں، یہ صرف حقیقی ڈیٹا بتائے گا۔',
    nicht_3: 'ماڈل کے بہت سے اعداد سوچے سمجھے مفروضے ہیں، مثلاً کامیابی کے بعد کوئی حصہ کتنا پختہ ہوتا ہے۔ یہ زیادہ تر فلیش کارڈ کی تحقیق سے آئے ہیں، قرآن سے نہیں۔',
    nicht_4: 'ماڈل آپ کی اپنی جانچ سے سیکھتا ہے۔ جو غلطیاں چھپاتا ہے وہ سب سے زیادہ اپنا نقصان کرتا ہے: کمزور ترین مقامات دیر تک چھپے رہتے ہیں۔',
    nicht_5: 'اس کے علاوہ ملتے جلتے مقامات (متشابہات)، رمضان اور بیماری میں اثر اور بڑی عمر میں سیکھنا بھی کھلے سوال ہیں۔',
    pruefung_h: 'اسے کیسے جانچا جاتا ہے',
    pruefung_1: '<b>اختیاری سیکھنے کا ریکارڈ۔</b> آپ کی اجازت سے ایپ ہر مشق پر ایک بے ترتیب نمبر کے تحت ایک سطر بھیجتی ہے، بغیر نام، بغیر ای میل پتے اور بغیر ریکارڈنگ کے۔ یہ ترتیبات میں «تحقیق» کے تحت ملتا ہے اور آپ کسی بھی وقت اجازت واپس لے سکتے ہیں۔',
    pruefung_2: '<b>ایک سال بعد نظرثانی۔</b> تب ہم ماڈل کو اس ڈیٹا پر جانچیں گے اور جہاں وہ نہ ٹکے وہاں بدلیں گے۔',
    pruefung_3: '<b>بے ترتیب موازنہ (منصوبہ بند)۔</b> دو منصوبے ایک ہی شخص کے حصوں پر بے ترتیب طریقے سے بانٹے جاتے ہیں۔ آٹھ سے بارہ ہفتے بعد حصے بغیر اطلاع سنائے جاتے ہیں اور ایسا استاد جانچتا ہے جسے تقسیم کا علم نہیں۔',
    versprechen_h: 'اتقان کیا وعدہ نہیں کرتا',
    versprechen_1: 'اتقان کسی استاد کی جگہ نہیں لیتا۔ جو قرآن سکھاتا ہے اور آپ کی تلاوت سنتا ہے، اس کا کوئی بدل نہیں۔',
    versprechen_2: 'اتقان حفظ میں کسی خاص کامیابی کی ضمانت نہیں دیتا۔ منصوبہ دہرائی میں مدد دیتا ہے، دہرانا آپ کا اپنا کام رہتا ہے۔',
    versprechen_3: 'اس صفحے کے فیصد سمولیشن کو بیان کرتے ہیں۔ وہ آپ کی اپنی تعلیم کا وعدہ نہیں۔',
    stand: 'صورتِ حال: نومبر 2026۔ ماخذ: سیکھنے کے ماڈل کی دستاویز اور {welten} آزمائشی دنیاؤں والی سمولیشن کا حتمی امتحان۔',
    frage: 'کچھ غیر واضح یا غلط ہے؟ ہم تنقید کا خیرمقدم کرتے ہیں۔',
  },
