    teilen_auf_iphone_und_android_direkt_aus: 'iPhone اور اینڈرائیڈ پر سیدھا ایپ سے شیئر، کمپیوٹر پر تصویر کی فائل کے طور پر۔ نام کے ساتھ یا بغیر۔',
    jeder_tag_hat_sein_zeichen_erfuellt: 'ہر دن کی اپنی علامت ہے: مکمل، قضا، جزوی، آرام کا دن یا چھوٹ گیا۔ نیچے سب کچھ الفاظ میں بھی ہے۔',
    das_bild_entsteht_auf_deinem_geraet_und: 'تصویر آپ کے آلے پر بنتی ہے اور آپ کی ظاہری شکل کے مطابق ہوتی ہے، روشن یا تاریک۔',
